const raw = $json.stdout ?? '';
if (!raw) {
  throw new Error('war_room_governor.py returned no stdout.');
}
const payload = JSON.parse(raw);
return [{ json: payload }];

const probe = $json.probe ?? {};
const briefing = $json.briefing ?? {};
const blockers = (probe.critical_blockers ?? []).map((item) => `${item.component}: ${item.detail}`);
const alerts = (briefing.alerts ?? []).map((item) => `${item.severity} - ${item.alert}`);
return [{
  json: {
    headline: probe.has_critical_blocker ? 'Blocked' : 'Ready',
    blockerSummary: blockers.length ? blockers.join(' | ') : 'No critical blockers.',
    nextAction: probe.next_action ?? 'No recommendation.',
    latestRegime: briefing.snapshot?.latest_regime ?? null,
    latestComposite: briefing.snapshot?.latest_composite ?? null,
    latestPrice: briefing.snapshot?.latest_price ?? null,
    hotZone: briefing.snapshot?.hot_zone ?? null,
    hotZonePressure: briefing.snapshot?.hot_zone_pressure ?? null,
    marketSource: briefing.market_source ?? null,
    nodeSource: briefing.node_source ?? null,
    alertCount: alerts.length,
    alerts,
    briefing: briefing.briefing ?? [],
    readiness: briefing.readiness ?? [],
    probe,
    briefingPayload: briefing
  }
}];
